declare actor uuid := auth.uid();
begin
 if actor is null then raise exception 'Staff identity required' using errcode='42501'; end if;
 insert into public.followup_task_events(organization_id,task_id,actor_user_id,action,before_state,after_state)
 values(new.organization_id,new.id,actor,case when tg_op='INSERT' then 'created' else 'updated' end,
 case when tg_op='UPDATE' then jsonb_build_object('title',old.title,'status',old.status,'due_on',old.due_on,'assigned_user_id',old.assigned_user_id,'revision',old.revision) else null end,
 jsonb_build_object('title',new.title,'status',new.status,'due_on',new.due_on,'assigned_user_id',new.assigned_user_id,'revision',new.revision));
 return new;
end

DECLARE actor uuid:=auth.uid(); sid uuid; expiry timestamptz; valid boolean; claims jsonb:=auth.jwt();
BEGIN
 BEGIN
  sid:=(claims->>'session_id')::uuid;
  IF coalesce(claims->>'exp','') !~ '^[0-9]{1,12}$' THEN RAISE invalid_text_representation; END IF;
  expiry:=to_timestamp((claims->>'exp')::bigint);
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
  RAISE EXCEPTION 'Decision access unavailable' USING ERRCODE='42501';
 END;
 IF actor IS NULL OR sid IS NULL OR expiry<=clock_timestamp() THEN
  RAISE EXCEPTION 'Decision access unavailable' USING ERRCODE='42501';
 END IF;
 SELECT email_confirmed_at IS NOT NULL AND NOT coalesce(is_anonymous,false)
  AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=clock_timestamp()) INTO valid
 FROM auth.users WHERE id=actor FOR SHARE;
 IF valid IS DISTINCT FROM true THEN RAISE EXCEPTION 'Decision access unavailable' USING ERRCODE='42501'; END IF;
 SELECT not_after IS NULL OR not_after>clock_timestamp() INTO valid FROM auth.sessions WHERE id=sid AND user_id=actor FOR SHARE;
 IF valid IS DISTINCT FROM true OR expiry<=clock_timestamp() THEN RAISE EXCEPTION 'Decision access unavailable' USING ERRCODE='42501'; END IF;
 RETURN actor;
END

declare actor uuid := auth.uid();
begin
 if actor is null or not exists(select 1 from auth.users where id=actor and email_confirmed_at is not null and not coalesce(is_anonymous,false)) then
  raise exception 'Verified staff identity required' using errcode='42501';
 end if;
 -- Only a matching, server-created in-transaction run can authorize automated insertion.
 if not (tg_op='INSERT' and new.workflow_run_id is not null and exists(
  select 1 from public.tag_workflow_runs r where r.id=new.workflow_run_id and r.organization_id=new.organization_id
   and r.status='building' and r.execution_actor_user_id=actor and r.reserved_task_id=new.id
   and r.person_id=new.person_id and r.task_title=new.title and r.leader_user_id=new.assigned_user_id and r.due_on is not distinct from new.due_on
 )) and (select count(*) from private.effective_staff_permissions where organization_id=new.organization_id and user_id=actor and revoked_at is null and permission in ('people.read','followup.read','followup.manage'))<>3 then
  raise exception 'Follow-up management permission required' using errcode='42501';
 end if;
 if tg_op='UPDATE' and (new.organization_id<>old.organization_id or new.person_id<>old.person_id or new.created_by<>old.created_by or new.id<>old.id or new.workflow_run_id is distinct from old.workflow_run_id) then
  raise exception 'Task identity cannot be changed' using errcode='42501';
 end if;
 if new.assigned_user_id is not null and (tg_op='INSERT' or new.assigned_user_id is distinct from old.assigned_user_id) then
  if (select count(*) from private.effective_staff_permissions where organization_id=new.organization_id and user_id=new.assigned_user_id and revoked_at is null and permission in ('people.read','followup.read'))<>2 then
   raise exception 'Assignee lacks access to this organization' using errcode='42501';
  end if;
 end if;
 new.title:=btrim(new.title); new.updated_at:=clock_timestamp();
 if tg_op='INSERT' then new.created_by:=actor; new.created_at:=new.updated_at; new.revision:=1; new.status:='open';
 else new.revision:=old.revision+1; new.created_at:=old.created_at; end if;
 return new;
end

